// Unit tests for the andesim CLI parser (parse_cli).
//
// Plain assert-and-count harness (no doctest dependency on the driver side).
// Exits non-zero if any check fails. Run by tests/andes_sim/test_andes_sim_f1.sh
// and, later, the F5+ infra tests.
#include <string>
#include <vector>

#include "cli.hpp"
#include "test_check.hpp"

using andes_sim::Cli;
using andes_sim::parse_cli;

int main() {
  // Selection axes, space-separated form.
  {
    Cli c = parse_cli({"run", "--mode", "fast", "--engine",
                       "vsim:ax45mpv_premium", "--trigger", "marker",
                       "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.subcommand == "run");
    CHECK(c.model == "fast");
    CHECK(c.engine == "vsim:ax45mpv_premium");
    CHECK(c.trigger == "marker");
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
    CHECK(!c.has_passthrough);
    CHECK(c.passthrough.empty());
  }

  // Selection axes, --flag=value form.
  {
    Cli c = parse_cli({"run", "--mode=cycle", "--engine=vsim:x"});
    CHECK(c.error.empty());
    CHECK(c.model == "cycle");
    CHECK(c.engine == "vsim:x");
  }

  // The `--` boundary: everything after it is verbatim passthrough, even
  // tokens that look like framework flags (they must NOT be parsed).
  {
    Cli c = parse_cli({"run", "--mode", "fast", "prog.elf", "--", "-gdb",
                       "tcp::1234", "-S", "--mode", "IGNORED"});
    CHECK(c.error.empty());
    CHECK(c.model == "fast");
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
    CHECK(c.has_passthrough);
    CHECK(c.passthrough.size() == 5);
    CHECK(c.passthrough[0] == "-gdb");
    CHECK(c.passthrough[1] == "tcp::1234");
    CHECK(c.passthrough[4] == "IGNORED");
  }

  // A `--` with nothing after it still marks passthrough (empty argv).
  {
    Cli c = parse_cli({"run", "--mode", "fast", "--"});
    CHECK(c.error.empty());
    CHECK(c.has_passthrough);
    CHECK(c.passthrough.empty());
  }

  // Per-subcommand help.
  {
    Cli c = parse_cli({"run", "-h"});
    CHECK(c.subcommand == "run");
    CHECK(c.help);
  }
  {
    Cli c = parse_cli({"list", "--help"});
    CHECK(c.subcommand == "list");
    CHECK(c.help);
  }

  // Top-level help: no subcommand.
  {
    Cli c = parse_cli({"-h"});
    CHECK(c.subcommand.empty());
    CHECK(c.help);
  }

  // list positional target.
  {
    Cli c = parse_cli({"list", "fixtures"});
    CHECK(c.subcommand == "list");
    CHECK(c.positional.size() == 1 && c.positional[0] == "fixtures");
  }

  // Hybrid pc-trigger boundaries (symbol + 0x address), space-separated form.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--trigger", "pc",
                       "--pc-start", "main", "--pc-end", "0x80001234",
                       "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.pc_start == "main");
    CHECK(c.pc_end == "0x80001234");
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
  }

  // Hybrid mem size; mixes space and =forms.
  // --mmap-size is the retired spelling, kept as a hidden alias of --mem-size.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--trigger", "marker",
                       "--mmap-size=64M", "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.mem_size == "64M");
  }

  // The icount/warmup knobs were removed: --qemu-icount / --vsim-icount /
  // --vsim-warmup-icount are now unknown options.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--qemu-icount", "10",
                       "prog.elf"});
    CHECK(!c.error.empty());
    Cli d = parse_cli({"run", "--mode", "hybrid", "--vsim-icount", "10",
                       "prog.elf"});
    CHECK(!d.error.empty());
    Cli e = parse_cli({"run", "--mode", "hybrid", "--vsim-warmup-icount", "500",
                       "prog.elf"});
    CHECK(!e.error.empty());
  }

  // --what was a placeholder for a never-wired `build` subcommand: it parsed
  // but no command read it, so it silently swallowed its value everywhere.
  // Removed -- now an unknown option like any other.
  {
    Cli c = parse_cli({"run", "--mode", "fast", "--what", "driver", "prog.elf"});
    CHECK(!c.error.empty());
  }

  // --mem-size is the documented spelling (works on every model).
  {
    Cli c = parse_cli({"run", "--mode", "fast", "--mem-size", "2G",
                       "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.mem_size == "2G");
  }

  // Absent hybrid flags stay empty -- cmd_run supplies the real defaults.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.pc_start.empty());
    CHECK(c.mem_size.empty());
  }

  // kanata/objdump pass-through flags parse like the rest (space + =form).
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--kanata", "k.txt",
                       "--objdump=o.txt", "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.kanata == "k.txt");
    CHECK(c.objdump == "o.txt");
  }

  // --verify is a boolean (oracle differential verification), default off.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--verify", "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.verify);
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
    Cli d = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
    CHECK(!d.verify);
  }

  // --print-memmap is a boolean (print the hybrid guest memory map and
  // exit), default off; the ELF stays optional for it (cmd_run's rule).
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--print-memmap"});
    CHECK(c.error.empty());
    CHECK(c.print_memmap);
    CHECK(c.positional.empty());
    Cli d = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
    CHECK(!d.print_memmap);
  }

  // --gdb is a boolean, default off; valid on fast and cycle.
  {
    Cli c = parse_cli({"run", "--mode", "fast", "--gdb", "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.gdb);
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
    Cli d = parse_cli({"run", "--mode", "cycle", "prog.elf"});
    CHECK(!d.gdb);
  }

  // `run` is the default command: a first token that is not a known
  // subcommand parses exactly like `run ...` -- flag-first form.
  {
    Cli c = parse_cli({"--mode", "fast", "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.subcommand == "run");
    CHECK(c.model == "fast");
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
  }

  // ... and ELF-first form.
  {
    Cli c = parse_cli({"prog.elf", "--mode", "fast"});
    CHECK(c.error.empty());
    CHECK(c.subcommand == "run");
    CHECK(c.model == "fast");
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
  }

  // The implicit form still honors the `--` passthrough boundary.
  {
    Cli c = parse_cli({"--mode", "fast", "prog.elf", "--", "-S"});
    CHECK(c.error.empty());
    CHECK(c.subcommand == "run");
    CHECK(c.has_passthrough);
    CHECK(c.passthrough.size() == 1 && c.passthrough[0] == "-S");
  }

  // Explicit subcommands are untouched by the default: `list`/`doctor`
  // first tokens stay subcommands, not positionals.
  {
    Cli c = parse_cli({"doctor"});
    CHECK(c.subcommand == "doctor");
    CHECK(c.positional.empty());
  }

  // --log-level parses like the other value options (space + =form) and
  // defaults to empty (cmd dispatch applies the real default, info).
  {
    Cli c = parse_cli({"run", "--mode", "fast", "--log-level", "1", "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.log_level == "1");
    Cli d = parse_cli({"--log-level=4", "--mode", "fast", "prog.elf"});
    CHECK(d.error.empty());
    CHECK(d.log_level == "4");
    CHECK(d.subcommand == "run");
    Cli e = parse_cli({"run", "--mode", "fast", "prog.elf"});
    CHECK(e.log_level.empty());
  }

  // Unknown option before `--` is an error.
  {
    Cli c = parse_cli({"run", "--bogus"});
    CHECK(!c.error.empty());
  }

  // A selection flag with no value is an error.
  {
    Cli c = parse_cli({"run", "--mode"});
    CHECK(!c.error.empty());
  }

  // --model was renamed to --mode (clean break): the old spelling no longer
  // parses -- it falls through to the unknown-option error.
  {
    Cli c = parse_cli({"run", "--model", "fast", "prog.elf"});
    CHECK(!c.error.empty());
  }

  return andes_sim::test::report("cli parse");
}

#include "cli.hpp"

namespace andes_sim {
namespace {

// Try to read an option's value at args[i]. Supports both `--flag value`
// (consumes the next token, advancing i) and `--flag=value`.
//   returns  1 = matched, `out` set
//            0 = this token is not `flag`
//           -1 = matched `--flag` but no value follows
int match_opt(const std::vector<std::string>& args, size_t& i,
              const std::string& flag, std::string& out) {
  const std::string& a = args[i];
  if (a == flag) {
    if (i + 1 >= args.size()) return -1;
    out = args[++i];
    return 1;
  }
  const std::string pfx = flag + "=";
  if (a.starts_with(pfx)) {
    out = a.substr(pfx.size());
    return 1;
  }
  return 0;
}

}  // namespace

bool is_subcommand(std::string_view name) {
  return name == "run" || name == "list" || name == "doctor";
}

Cli parse_cli(const std::vector<std::string>& args) {
  Cli c;
  if (args.empty()) return c;  // no subcommand; caller prints usage

  // First token is the subcommand, unless it is a top-level help request.
  if (args[0] == "-h" || args[0] == "--help") {
    c.help = true;
    return c;
  }

  // `run` is the default command: any other first token is `run`'s own
  // first argument (a flag or the ELF), not a subcommand.
  size_t first = 1;
  if (is_subcommand(args[0])) {
    c.subcommand = args[0];
  } else {
    c.subcommand = "run";
    first = 0;
  }

  for (size_t i = first; i < args.size(); ++i) {
    const std::string& a = args[i];

    if (a == "--") {  // the passthrough boundary: rest is verbatim
      c.has_passthrough = true;
      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
      break;
    }
    if (a == "-h" || a == "--help") {
      c.help = true;
      continue;
    }
    if (a == "--dry-run") {
      c.dry_run = true;
      continue;
    }
    if (a == "--print-memmap") {
      c.print_memmap = true;
      continue;
    }
    if (a == "--verify") {
      c.verify = true;
      continue;
    }
    if (a == "--gdb") {
      c.gdb = true;
      continue;
    }

    const struct {
      const char* flag;
      std::string* out;
    } opts[] = {{"--mode", &c.model},
                {"--engine", &c.engine},
                {"--trigger", &c.trigger},
                {"--pc-start", &c.pc_start},
                {"--pc-end", &c.pc_end},
                {"--mem-size", &c.mem_size},
                {"--mmap-size", &c.mem_size},  // retired spelling, same knob
                {"--kanata", &c.kanata},
                {"--objdump", &c.objdump},
                {"--log-level", &c.log_level},
                {"--log-file", &c.log_file},
                {"--gdb-port", &c.gdb_port}};
    bool consumed = false;
    for (const auto& o : opts) {
      int r = match_opt(args, i, o.flag, *o.out);
      if (r < 0) { c.error = std::string("missing value for ") + o.flag; return c; }
      if (r > 0) { consumed = true; break; }
    }
    if (consumed) continue;

    if (a.size() > 1 && a[0] == '-') {
      c.error = "unknown option: " + a;
      return c;
    }
    c.positional.push_back(a);
  }

  return c;
}

Cli parse_cli(int argc, char** argv) {
  std::vector<std::string> args;
  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
  return parse_cli(args);
}

}  // namespace andes_sim

// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
// and future backends). One C++20 binary that selects a model (fast / cycle
// / hybrid), resolves engines at runtime, and either passes through to a single
// engine or orchestrates a hybrid round-trip.
//
// This file owns argument dispatch only: parse the CLI, route to a command.
#include <cstdio>
#include <cstdlib>
#include <exception>
#include <string>
#include <string_view>

#include "cli.hpp"
#include "dev_mode.hpp"
#include "log.hpp"

namespace andes_sim {
int cmd_list(const Cli& cli);
int cmd_doctor(const Cli& cli);
int cmd_run(const Cli& cli);
}  // namespace andes_sim

namespace {

using andes_sim::Cli;
using andes_sim::cmd_doctor;
using andes_sim::cmd_list;
using andes_sim::cmd_run;
using andes_sim::is_dev_mode;

// The known command names live in cli.cpp (is_subcommand): the parser needs
// them for the default-command rule, so parse_cli only ever yields run/list/
// doctor (or "" for no args / top-level help). Developer build/test/state-diff
// tooling lives in scripts/, not the binary.

// ---- help model: the user-facing surface rendered as a command tree --------
//
// `run`'s two subcommand groups -- the modes (the composition axis) ...
struct ModeRow {
  const char* name;
  const char* brief;
};
constexpr ModeRow kRunModes[] = {
    {"fast", "QEMU only -- functional, full speed"},
    {"cycle", "one cycle-accurate engine, from reset"},
    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
};

// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
struct TargetRow {
  const char* name;
  const char* brief;
  bool dev;
};
constexpr TargetRow kListTargets[] = {
    {"models", "the modes and their engines", false},
    {"engines", "discovered cycle-accurate engines", false},
    {"fixtures", "internal test ELFs (developer target)", true},
};

// ... and `run`'s options. Each `flag` carries its own leading indent (the pc
// boundaries nest under --trigger pc). `tag` marks a required option (and WHEN
// it is required); `dev` hides it unless ANDESIM_DEV is set.
struct OptRow {
  const char* flag;  // includes its own leading indent
  const char* tag;
  const char* brief;
  bool dev;
};
constexpr OptRow kRunOpts[] = {
    {"  --mode fast|cycle|hybrid", "REQUIRED", "which mode to run", false},
    {"  --trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter", false},
    {"    --pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary", false},
    {"    --pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary", false},
    {"  --engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)", false},
    {"  --mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)", false},
    {"  --dry-run", "", "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)", false},
    {"  --print-memmap", "", "print the hybrid guest memory map and exit, running nothing (hybrid only; ELF optional)", false},
    {"  --verify", "", "cross-check the hybrid run against a QEMU oracle", false},
    {"  --kanata <file>", "", "write a Kanata pipeline trace of the ROI (hybrid only; open in Konata)", false},
    {"    --objdump <file>", "", "embed that objdump -d dump's disassembly in the trace (requires --kanata)", false},
    {"  --gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)", false},
    {"  --gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)", false},
    {"  --log-level <0-6>", "", "verbosity, vsim's scale: 0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off (default 2: program output + the cycle figure)", false},
    {"  --log-file <file>", "", "append EVERY level's messages (timestamped) to <file>; the console keeps --log-level", false},
    {"  -- <args...>", "", "forward everything after -- verbatim to the engine (fast/cycle only; hybrid rejects -- args)", false},
};

// A major command line at column 0: `name   brief`.
void print_major(std::FILE* out, const char* name, const char* brief) {
  std::fprintf(out, "%-7s %s\n", name, brief);
}

// A subcommand/target line, indented two under its command: `  name   brief`.
void print_sub(std::FILE* out, const char* name, const char* brief) {
  std::fprintf(out, "  %-9s %s\n", name, brief);
}

// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
void print_opt(std::FILE* out, const OptRow& o) {
  if (o.tag[0])
    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
  else
    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
}

// `run`: major line, the mode subcommands, then the option list (dev options
// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
void print_run_block(std::FILE* out) {
  print_major(out, "run", "run one simulation (the default: 'run' may be omitted)");
  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
  std::fputs("\n", out);
  for (const OptRow& o : kRunOpts) {
    if (o.dev && !is_dev_mode()) continue;
    print_opt(out, o);
  }
}

void print_list_block(std::FILE* out) {
  print_major(out, "list", "list what is available");
  for (const TargetRow& t : kListTargets) {
    if (t.dev && !is_dev_mode()) continue;
    print_sub(out, t.name, t.brief);
  }
}

void print_doctor_block(std::FILE* out) {
  print_major(out, "doctor", "check toolchain + fixtures are present");
}

// Top-level `andesim --help`: the whole tree -- every major command, its
// subcommands, and run's full option list, so one screen shows everything.
void print_usage(std::FILE* out) {
  std::fputs("usage: andesim [command] [options] <ELF> [-- <engine args>]\n\n",
             out);
  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
             out);
  print_run_block(out);
  std::fputs("\n", out);
  print_list_block(out);
  std::fputs("\n", out);
  print_doctor_block(out);
  std::fputs(
      "\n'andesim run --help' / 'andesim list --help' for per-command "
      "detail.\n",
      out);
}

// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
// parse_cli admits only run/list/doctor, so `run` is the fallthrough.
void print_subcommand_help(std::string_view name, std::FILE* out) {
  if (name == "list") { print_list_block(out); return; }
  if (name == "doctor") { print_doctor_block(out); return; }
  print_run_block(out);
}

}  // namespace

int main(int argc, char** argv) {
  using namespace andes_sim;

  Cli cli = parse_cli(argc, argv);
  if (!cli.error.empty()) {
    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
    return 2;
  }

  if (!set_log_threshold(cli.log_level)) {
    std::fprintf(stderr,
                 "andesim: invalid --log-level '%s' (0=trace 1=debug 2=info "
                 "3=warn 4=error 5=critical 6=off)\n",
                 cli.log_level.c_str());
    return 2;
  }
  if (!set_log_file(cli.log_file)) {
    std::fprintf(stderr, "andesim: cannot open --log-file '%s' for append\n",
                 cli.log_file.c_str());
    return 2;
  }

  if (cli.subcommand.empty()) {  // no command, or top-level -h
    if (cli.help) {
      print_usage(stdout);
      return 0;
    }
    print_usage(stderr);
    return 2;
  }

  if (cli.help) {
    print_subcommand_help(cli.subcommand, stdout);
    return 0;
  }

  if (cli.subcommand == "list") return cmd_list(cli);
  if (cli.subcommand == "doctor") return cmd_doctor(cli);
  return cmd_run(cli);  // parse_cli admits only run/list/doctor
}

// andesim command-line parsing.
//
// The grammar is deliberately tiny and stable across all subcommands:
//
//   andesim [<cmd>] [--mode M] [--engine E] [--trigger T] [positional...]
//                   [-- <verbatim engine args...>]
//
// `run` is the default command: when the first token is not a known
// subcommand (and not a top-level help flag), the whole line parses as
// `run ...`, so `andesim --mode fast prog.elf` works without typing `run`.
//
// The single most important rule is the `--` boundary: every token after the
// first `--` is captured verbatim into `passthrough` and is NOT interpreted by
// the framework. That is what lets `fast`/`cycle` forward an engine's whole
// native CLI (e.g. `-gdb tcp::1234 -S`) untouched, so users see one simulator.
#ifndef ANDESIM_CLI_HPP
#define ANDESIM_CLI_HPP

#include <string>
#include <string_view>
#include <vector>

namespace andes_sim {

// True for the known command names (run/list/doctor). The single source of
// truth shared by the parser (default-command rule) and main's dispatch.
bool is_subcommand(std::string_view name);

struct Cli {
  std::string subcommand;                 // e.g. "run", "list"; "" if none
  std::string model;                      // --mode fast|cycle|hybrid (field stays 'model': the concept, see list models)
  std::string engine;                     // --engine <id>
  std::string trigger;                    // --trigger marker|pc
  // Hybrid trigger args (empty => cmd_run applies the default). pc boundaries
  // are a symbol name or 0x address; the sizes stay strings here and are
  // parsed where they are used.
  std::string pc_start;                   // --pc-start (trigger pc)
  std::string pc_end;                     // --pc-end   (trigger pc)
  std::string mem_size;                   // --mem-size (guest memory; --mmap-size is a hidden alias)
  std::string kanata;                     // --kanata <file> (marker/pc ROI trace)
  std::string objdump;                    // --objdump <file> (kanata labels)
  std::string log_level;                  // --log-level 0..6 (vsim scale; "" => info)
  std::string log_file;                   // --log-file <path> (full trace capture)
  std::vector<std::string> positional;    // non-flag framework args
  std::vector<std::string> passthrough;   // verbatim, everything after `--`
  bool help = false;                      // -h / --help (before `--`)
  bool dry_run = false;                   // --dry-run (build, run, test, ...)
  bool print_memmap = false;              // --print-memmap (run --mode hybrid)
  bool verify = false;                    // --verify (run --mode hybrid)
  bool gdb = false;                       // --gdb (fast: QEMU gdbstub; cycle: vsim JTAG + ICEman)
  std::string gdb_port;                   // --gdb-port (fast: default 1234; cycle: default 9104)
  bool has_passthrough = false;           // a `--` boundary was present
  std::string error;                      // non-empty => parse failed
};

// Parse argv[1..] (program name skipped). The vector overload is the testable
// core; the argv overload adapts it for main().
Cli parse_cli(const std::vector<std::string>& args);
Cli parse_cli(int argc, char** argv);

}  // namespace andes_sim

#endif  // ANDESIM_CLI_HPP

