1	/* HVM content transport e2e (ROADMAP_hvm F4): HVM data round-trip.
2	 *
3	 *   QEMU 1: fill the whole 256 KB HVM window (0x90000000 aperture, plain
4	 *           RAM in QEMU, no enable bit) with a runtime-COMPUTED pattern.
5	 *   vsim:   inside the ROI, pull three sampled windows back out of the RTL
6	 *           HVM SRAM with VECTOR loads (vle32 -> vse32 -> scalar compare),
7	 *           then print the verdict (HVM_OK / HVM_BAD). The harness greps the
8	 *           vsim log (CHECK_VSIM_STDOUT=HVM_OK). The windows pin the spots
9	 *           the backdoor could get wrong: bank0 head, the bank0/bank1
10	 *           boundary straddle (bank = addr bit 17), and bank1 tail.
11	 *
12	 * Why this is decisive for the transport: the pattern bytes exist NOWHERE
13	 * except the HVM. They are runtime-computed (not in the ELF), and QEMU's
14	 * HVM RAM is NOT backed by the shared DRAM mmap. The ONLY road to the vsim
15	 * RTL's HVM SRAM is the sidecar transport: plugin drain -> <state>.hvm ->
16	 * --hvm backdoor load. No transport => vsim reads reset-empty SRAM =>
17	 * HVM_BAD.
18	 *
19	 * Totality is covered by the harness, not the ROI: CHECK_LM_EXIT_SIDECARS
20	 * compares the vsim exit dump (get_hvm) byte-for-byte against the entry
21	 * sidecar, all 256 KB. The in-ROI vector reads only need to prove the RTL
22	 * VPU->HVM path sees the loaded content (sampled, to keep the
23	 * cycle-accurate ROI short).
24	 */
25	#include "runtime/rt_c_helpers.h"
26	#include "runtime/memory_map.h"
27	
28	#include <stdint.h>
29	#include <stdio.h>
30	
31	#define HVM_BYTES 262144u
32	#define HVM_WORDS (HVM_BYTES / 4u)
33	#define WIN_WORDS 64u
34	
35	/* Per-word pattern: cheap, position-dependent, never all-zero. */
36	static inline uint32_t pat(uint32_t i) { return i * 2654435761u + 0x5A17u; }
37	
38	/* Copy n words out of the HVM through the VECTOR unit (vle32 loads the
39	 * aperture, vse32 spills to a DRAM buffer for the scalar compare). Like
40	 * rt_c_v_fill, v8 is used without a clobber: -O1 never touches V regs. */
41	static void v_copy_words(uint32_t src_word, uint32_t *dst, uint32_t n)
42	{
43	  const uint32_t *src =
44	    (const uint32_t *) (uintptr_t) (HVM_BASE + src_word * 4u);
45	  while (n) {
46	    unsigned long vl;
47	    asm volatile("vsetvli %0, %1, e32, m1, ta, ma\n\t"
48	                 "vle32.v v8, (%2)\n\t"
49	                 "vse32.v v8, (%3)"
50	                 : "=&r"(vl)
51	                 : "r"((unsigned long) n), "r"(src), "r"(dst)
52	                 : "memory");
53	    src += vl;
54	    dst += vl;
55	    n -= (uint32_t) vl;
56	  }
57	}
58	
59	/* Returns the number of mismatching words in [w0, w0+WIN_WORDS). */
60	static uint32_t check_window(uint32_t w0)
61	{
62	  uint32_t buf[WIN_WORDS];
63	  v_copy_words(w0, buf, WIN_WORDS);
64	  uint32_t bad = 0;
65	  for (uint32_t i = 0; i < WIN_WORDS; i++)
66	    if (buf[i] != pat(w0 + i)) bad++;
67	  return bad;
68	}
69	
70	int main(void)
71	{
72	  volatile uint32_t *hvm = (volatile uint32_t *) (uintptr_t) HVM_BASE;
73	
74	  /* QEMU phase: runtime-computed fill of the whole window. Also init stdio
75	   * here so the ROI's verdict printf does not pay first-call setup. */
76	  for (uint32_t i = 0; i < HVM_WORDS; i++) hvm[i] = pat(i);
77	  printf("HVM filled\n");
78	  fflush(stdout);
79	
80	  enter_vsim();
81	
82	  /* vsim ROI: sampled vector readback. Window starts: bank0 head, the
83	   * bank boundary straddle (32 words each side of word 32768), bank1
84	   * tail. */
85	  uint32_t bad = 0;
86	  bad += check_window(0);
87	  bad += check_window(HVM_WORDS / 2u - WIN_WORDS / 2u);
88	  bad += check_window(HVM_WORDS - WIN_WORDS);
89	  if (bad == 0) {
90	    printf("HVM_OK sampled=%u\n", (unsigned) (3 * WIN_WORDS));
91	  } else {
92	    printf("HVM_BAD count=%u\n", (unsigned) bad);
93	  }
94	  fflush(stdout);
95	
96	  exit_vsim();
97	
98	  return bad != 0;
99	}
100

