/* RVV intrinsics inside the ROI: an 8x8x8 single-precision GEMM.
 *
 * The other demos move DATA across the hybrid handoff; this one moves
 * COMPUTE. The ROI runs a vector kernel written with the standard RVV
 * intrinsics (<riscv_vector.h>), proving
 *   - the toolchain's RVV intrinsics compile and run on every mode,
 *   - on hybrid, the vector unit works right after the handoff: the
 *     restored mstatus.VS and V CSRs let the ROI issue vector
 *     instructions with no V setup code of its own.
 *
 * QEMU phase (before the ROI):
 *   - fill A and B with runtime-computed small integers (exact in fp32)
 *   - compute the scalar reference C_ref
 *
 * vsim ROI:
 *   - C = A x B with vle32/vfmacc/vse32, strip-mined by vsetvl so the
 *     kernel is correct for any VLEN
 *   - compare C with C_ref; prints GEMM_OK / GEMM_BAD
 *
 * All operands are integer-valued floats with every intermediate far
 * below 2^24, so scalar mul+add and vector fmacc round nothing and the
 * comparison can be exact. A, B, C_ref live in normal DRAM -- the
 * shared mmap -- which is how they survive the QEMU -> vsim handoff.
 */

#include <stdint.h>
#include <stdio.h>
#include <riscv_vector.h>
#include <andesim/ROI.h>

#define N 8

static float A[N][N], B[N][N], C[N][N], C_ref[N][N];

/* Integer-valued in [-8, 7] -- exact in fp32. */
static inline float elem(uint32_t i, uint32_t salt)
{
  uint32_t h = (i + salt) * 2654435761u;
  return (float) (int) (h >> 28) - 8.0f;
}

/* ROI body, noinline and non-static so --trigger pc can name it. */
__attribute__((noinline)) int gemm_kernel(void)
{
  for (int i = 0; i < N; i++) {
    int j = 0;
    while (j < N) {
      size_t vl = __riscv_vsetvl_e32m1((size_t) (N - j));
      vfloat32m1_t acc = __riscv_vfmv_v_f_f32m1(0.0f, vl);
      for (int k = 0; k < N; k++) {
        vfloat32m1_t b = __riscv_vle32_v_f32m1(&B[k][j], vl);
        acc = __riscv_vfmacc_vf_f32m1(acc, A[i][k], b, vl);
      }
      __riscv_vse32_v_f32m1(&C[i][j], acc, vl);
      j += (int) vl;
    }
  }

  uint32_t bad = 0;
  for (int i = 0; i < N; i++)
    for (int j = 0; j < N; j++)
      bad += (C[i][j] != C_ref[i][j]);

  if (bad != 0) {
    printf("GEMM_BAD count=%u\n", (unsigned) bad);
    return 1;
  }
  printf("GEMM_OK n=%u\n", (unsigned) (N * N));
  return 0;
}

int main(void)
{
  for (int i = 0; i < N; i++)
    for (int k = 0; k < N; k++) {
      A[i][k] = elem((uint32_t) (i * N + k), 0xA11Au);
      B[i][k] = elem((uint32_t) (i * N + k), 0xB22Bu);
    }

  for (int i = 0; i < N; i++)
    for (int j = 0; j < N; j++) {
      float s = 0.0f;
      for (int k = 0; k < N; k++) s += A[i][k] * B[k][j];
      C_ref[i][j] = s;
      C[i][j] = 0.0f;
    }
  printf("GEMM 8x8x8 staged\n");

  andesim_ROI_begin();
  int rc = gemm_kernel();
  andesim_ROI_end();
  /* ROI end symbol for --pc-end: the point right after the call. */
  __asm__ __volatile__(".globl gemm_roi_end\ngemm_roi_end:" ::: "memory");

  return rc;
}

