142	    if (results[0].execs == 0)
143	    { /* if not supplied, execute all algorithms */
144	        results[0].execs = ALL_ALGORITHMS_MASK;
145	    }
146	    /* put in some default values based on one seed only for easy testing */
147	    if ((results[0].seed1 == 0) && (results[0].seed2 == 0)
148	        && (results[0].seed3 == 0))
149	    { /* performance run */
150	        results[0].seed1 = 0;
151	        results[0].seed2 = 0;
152	        results[0].seed3 = 0x66;
153	    }
